package com.casystem.onboarding.controller;
import com.casystem.onboarding.dto.AuthRequest;import com.casystem.onboarding.model.User;import com.casystem.onboarding.repository.UserRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthControllerTest{UserRepository users;PasswordEncoder enc;AuditService audit;TokenService tokens;HttpServletRequest req;AuthController c;@BeforeEach void set(){users=mock(UserRepository.class);enc=mock(PasswordEncoder.class);audit=mock(AuditService.class);tokens=mock(TokenService.class);req=mock(HttpServletRequest.class);when(req.getRemoteAddr()).thenReturn("1.2.3.4");c=new AuthController(users,enc,audit,tokens);}
 @Test void registroValidaCampos(){assertEquals(400,c.register(new AuthRequest(null,"x",""),req).getStatusCode().value());}
 @Test void registroDuplicado(){when(users.findByEmailAndDeletedFalse("a@b.com")).thenReturn(Optional.of(new User()));assertEquals(400,c.register(new AuthRequest("a@b.com","123456","Ana"),req).getStatusCode().value());}
 @Test void registraUsuario(){when(users.findByEmailAndDeletedFalse(" A@B.COM ")).thenReturn(Optional.empty());when(enc.encode("123456")).thenReturn("hash");when(users.save(any())).thenAnswer(i->{User u=i.getArgument(0);u.setId(5L);return u;});assertEquals(200,c.register(new AuthRequest(" A@B.COM ","123456"," Ana "),req).getStatusCode().value());verify(users).save(argThat(u->u.getEmail().equals("a@b.com")&&u.getPassword().equals("hash")&&u.getName().equals("Ana")));verify(audit).log(5L,"Usuario registrado","1.2.3.4");}
 @Test void loginCorrecto(){User u=new User();u.setId(2L);u.setEmail("a@b.com");u.setPassword("h");u.setName("Ana");when(users.findByEmailAndDeletedFalse("a@b.com")).thenReturn(Optional.of(u));when(enc.matches("123456","h")).thenReturn(true);when(tokens.create(2L,"a@b.com")).thenReturn("jwt");assertEquals(200,c.login(new AuthRequest("A@B.COM","123456",null),req).getStatusCode().value());verify(audit).log(2L,"Inicio de sesión","1.2.3.4");}
 @Test void loginIncorrecto(){when(users.findByEmailAndDeletedFalse("x@y.com")).thenReturn(Optional.empty());assertEquals(401,c.login(new AuthRequest("x@y.com","bad",null),req).getStatusCode().value());}}
